mapper.select:
select ca.application_id, ca.club_id, c.club_name, c.logo_url, ca.user_id, ca.user_name, ca.nick_name, ca.student_id, ca.real_name, ca.gender, ca.major, ca.grade, ca.class_name, ca.phone, ca.email, ca.self_introduction, ca.apply_reason, ca.special_skills, ca.application_time, ca.review_status, ca.reviewer_id, ca.reviewer_name, ca.review_time, ca.review_comment, ca.del_flag, ca.create_by, ca.create_time, ca.update_by, ca.update_time, ca.remark from club_application ca left join club c on ca.club_id = c.club_id
ca.del_flag = '0' and ca.club_id = #{clubId} and c.club_name like concat('%', #{clubName}, '%') and ca.user_id = #{userId} and ca.user_name like concat('%', #{userName}, '%') and ca.nick_name like concat('%', #{nickName}, '%') and ca.real_name like concat('%', #{realName}, '%') and ca.review_status = #{status}
and ca.club_id in #{cid}
order by ca.application_time desc

mapper.update:
update club_application
club_id = #{clubId}, club_name = #{clubName}, user_id = #{userId}, user_name = #{userName}, nick_name = #{nickName}, student_id = #{studentId}, real_name = #{realName}, gender = #{gender}, major = #{major}, grade = #{grade}, class_name = #{className}, phone = #{phone}, email = #{email}, self_introduction = #{selfIntroduction}, apply_reason = #{applyReason}, special_skills = #{specialSkills}, application_time = #{applicationTime}, review_status = #{status}, reviewer_id = #{reviewerId}, reviewer_name = #{reviewerName}, review_time = #{reviewTime}, review_comment = #{reviewComment}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where application_id = #{applicationId}

mapper.select:
SELECT review_status as status, count(*) as count FROM club_application WHERE del_flag = '0'
AND club_id in #{cid}
GROUP BY review_status

SELECT DATE_FORMAT(application_time, '%m-%d') as day, count(*) as count FROM club_application WHERE del_flag = '0' AND application_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND club_id in #{cid}
GROUP BY day ORDER BY day ASC

SELECT c.club_name as clubName, c.club_id as clubId, count(*) as count FROM club_application ca LEFT JOIN club c ON ca.club_id = c.club_id WHERE ca.del_flag = '0'
AND ca.club_id in #{cid}
GROUP BY c.club_name, c.club_id ORDER BY count DESC LIMIT 10

SELECT review_status as status, count(*) as count FROM club_application WHERE del_flag = '0' AND DATE(application_time) = DATE_SUB(CURDATE(), INTERVAL 1 DAY)
AND club_id in #{cid}
GROUP BY review_status

SELECT DATE_FORMAT(ca.application_time, '%m-%d') as day, c.club_name as clubName, count(*) as count FROM club_application ca LEFT JOIN club c ON ca.club_id = c.club_id WHERE ca.del_flag = '0' AND ca.application_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND ca.club_id in #{cid}
GROUP BY day, c.club_name ORDER BY day ASC, c.club_name ASC

SELECT ca.review_status as status, c.club_name as clubName, count(*) as count FROM club_application ca LEFT JOIN club c ON ca.club_id = c.club_id WHERE ca.del_flag = '0'
AND ca.club_id in #{cid}
GROUP BY ca.review_status, c.club_name ORDER BY status, c.club_name
